const email = $input.first().json;

const EXTRACTION_PROMPT = `You are an expert B2B quote request parser for an industrial steel and metals distributor.
Extract structured data from the following quote request email.

IMPORTANT RULES:
- The email is in French (industrial B2B context)
- Product descriptions may contain jargon: "inox" = stainless steel, "Ø" = diameter, "lg" = length
- Common abbreviations: 304L, 316L (steel grades), HM (hexagonal), BLN (bolt), DN (nominal diameter)
- Quantities may use French notation: "200 pcs", "5 barres", "10 ml" (mètres linéaires)
- If information is not mentioned, use null (do NOT invent data)
- Extract ALL products mentioned, even if descriptions are vague
- References may look like: "TUBE-INOX-304L-25x1.5-6M" or "BHM-M12x50"
- For client_name, extract the company name if available, otherwise the person name
- For client_email, use the "from" field of the email

Return a JSON object with this exact schema:
{
  "client_name": "string or null",
  "client_email": "string or null",
  "products": [
    {
      "description": "product description as written by client",
      "reference": "product code/reference if mentioned, else null",
      "quantity": "quantity with unit as written",
      "specs": "any specs (dimensions, material, grade, finish) or null"
    }
  ],
  "delivery_date": "delivery date if mentioned, else null",
  "notes": "any additional context or requirements, else null"
}`;

const emailText = `From: ${email.from}\nSubject: ${email.subject}\nDate: ${email.date}\n\n${email.body}`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: 'gpt-4o',
      response_format: { type: 'json_object' },
      temperature: 0,
      messages: [
        { role: 'system', content: EXTRACTION_PROMPT },
        { role: 'user', content: emailText }
      ]
    }
  });

  const content = response.choices[0].message.content;
  let extracted;
  try {
    extracted = JSON.parse(content);
  } catch (parseErr) {
    return [{ json: {
      _fixture_file: email._fixture_file,
      _email_id: email.id,
      _error: 'JSON parse error',
      _raw_response: content
    }}];
  }

  // Validate required fields exist
  const requiredFields = ['client_name', 'client_email', 'products', 'delivery_date', 'notes'];
  for (const field of requiredFields) {
    if (!(field in extracted)) {
      extracted[field] = null;
    }
  }

  // Ensure products is an array
  if (!Array.isArray(extracted.products)) {
    extracted.products = [];
  }

  // Validate each product has required fields
  extracted.products = extracted.products.map(p => ({
    description: p.description || null,
    reference: p.reference || null,
    quantity: p.quantity || null,
    specs: p.specs || null
  }));

  return [{ json: {
    _fixture_file: email._fixture_file,
    _email_id: email.id,
    _email_from: email.from,
    _email_subject: email.subject,
    extraction: extracted
  }}];

} catch (err) {
  return [{ json: {
    _fixture_file: email._fixture_file,
    _email_id: email.id,
    _error: err.message
  }}];
}

// Collect all extraction results and produce a summary
const items = $input.all();
const results = [];
let successCount = 0;
let errorCount = 0;

for (const item of items) {
  const data = item.json;
  if (data._error) {
    errorCount++;
    results.push({
      file: data._fixture_file,
      email_id: data._email_id,
      status: 'ERROR',
      error: data._error
    });
  } else {
    successCount++;
    const ext = data.extraction;
    results.push({
      file: data._fixture_file,
      email_id: data._email_id,
      status: 'OK',
      client_name: ext.client_name,
      client_email: ext.client_email,
      product_count: ext.products ? ext.products.length : 0,
      delivery_date: ext.delivery_date,
      has_notes: ext.notes !== null
    });
  }
}

return [{ json: {
  summary: {
    total: items.length,
    success: successCount,
    errors: errorCount
  },
  results: results,
  extractions: items.map(i => i.json)
}}];
